def remove_Occ(str, ch):
    first_occurrence = str.find(ch)
    last_occurrence = str.rfind(ch)
    if first_occurrence == last_occurrence:
        return str[:first_occurrence] + str[first_occurrence+1:]
    else:
        return str[:first_occurrence] + str[first_occurrence+1:last_occurrence] + str[last_occurrence+1:]

