def closest_num(n):
    if n == 0:
        return 0
    elif n < 0:
        n = -n
    left = 0
    right = n
    while left < right:
        mid = (left + right) // 2
        if mid * mid == n:
            return mid
        elif mid * mid < n:
            left = mid + 1
        else:
            right = mid
    return left - 1

def closest_num(n):
    if n == 0:
        return 0
    elif n < 0:
        n = n * -1
    min_diff = float('inf')
    closest_num = 0
    for i in range(n):
        diff = n - i
        if diff < min_diff:
            min_diff = diff
            closest_num = i
    return closest_num

