def merge_sorted_list(*lists):
    merged = []
    for lst in lists:
        heapq.heapify(lst)
        merged.append(heapq.heappop(lst))
        while lst:
            heapq.heappush(lst, merged[-1])
            merged.append(heapq.heappop(lst))
    return merged

