def replace_max_specialchar(text, n):
    special_chars = [' ', ',', '.']
    max_occurrences = 0
    result = ''
    for char in text:
        if char in special_chars:
            max_occurrences = max(max_occurrences, text.count(char))
    for char in text:
        if char in special_chars or max_occurrences == 0:
            result += char
        else:
            result += char * (max_occurrences // len(special_chars))
            max_occurrences %= len(special_chars)
    return result

