def count_no_of_ways(n, k):
    if n == 1:
        return k
    if n == 2:
        return k * (k - 1)
    dp = [0] * n
    dp[0] = k
    dp[1] = k * k
    for i in range(2, n):
        dp[i] = dp[i - 1] + dp[i - 2] * (k - 1)
    return dp[n - 1]

